SELECT CAST(COUNT(DISTINCT CASE WHEN p.insulin_type IN ('basal', 'bolus', 'basal-bolus', 'sliding-scale') AND p.los <= 72 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.insulin_type IN ('basal', 'bolus', 'basal-bolus', 'sliding-scale') AND p.los > 72 THEN a.subject_id END), 0) AS proportion FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'F' AND p.age >= 44 AND p.age <= 49 AND p.type IN ('T2DM', 'HF') AND a.discharge_time - a.admission_time >= 72;